'use client';

import {useMemo} from 'react';
import {CommandPalette} from '@/components/ui/astryx-command-palette-empty';
import {Text} from '@astryxdesign/core/Text';
import {createStaticSource} from '@astryxdesign/core/Typeahead';

function CommandPaletteEmptyBasic() {
  const emptySource = useMemo(() => createStaticSource([]), []);

  return (
    <CommandPalette
      isOpen
      isInline
      onOpenChange={() => {}}
      searchSource={emptySource}
      emptyBootstrapText={
        <Text type="supporting" color="secondary">
          No commands available
        </Text>
      }
    />
  );
}

export default function CommandPaletteEmptyBasicDemo() {
  return (
    <div
      data-astryx-theme="neutral"
      data-theme="light"
      style={{colorScheme: 'light', display: 'contents'}}>
      <CommandPaletteEmptyBasic />
    </div>
  );
}
